//! Durable exact-replay cancellation for a founding device-bootstrap transaction.
//!
//! The body carries its idempotency identity. Garth canonicalizes it once and
//! callers persist those bytes before the first network attempt. Every retry
//! reuses the bytes; only the HTTP DPoP proof is regenerated by the transport.

use arkret_models_collaboration::contact_operations::{
    BootstrapMode, CancelDeviceBootstrapOutcome, CancelDeviceBootstrapRequestBody,
};
use arkret_wire::{Hash, IdempotencyKey, ProtocolOpaqueId};

use crate::{Error, Result};

use super::BoxSessionFuture;

pub const CANCEL_DEVICE_BOOTSTRAP_PATH: &str = "/_arkret/gate/account/device-bootstrap/cancel";

#[derive(Clone, Debug)]
pub struct PreparedDeviceBootstrapCancel {
    request: CancelDeviceBootstrapRequestBody,
    canonical_request: Vec<u8>,
}

impl PreparedDeviceBootstrapCancel {
    pub fn prepare(
        transaction_id: ProtocolOpaqueId,
        canonical_request_digest: Hash,
        idempotency_key: IdempotencyKey,
    ) -> Result<Self> {
        let request = CancelDeviceBootstrapRequestBody {
            transaction_id,
            mode: BootstrapMode::Founding,
            canonical_request_digest,
            idempotency_key,
        };
        let canonical_request = arkret_canonical::canonical_json_bytes(&request)?;
        Ok(Self {
            request,
            canonical_request,
        })
    }

    /// Restore caller-persisted bytes without normalizing a different JSON
    /// spelling into the original operation identity.
    pub fn restore(canonical_request: Vec<u8>) -> Result<Self> {
        let request: CancelDeviceBootstrapRequestBody =
            arkret_canonical::from_canonical_json_slice(&canonical_request)?;
        if request.mode != BootstrapMode::Founding {
            return Err(Error::Protocol(
                "only founding device-bootstrap transactions can be cancelled here".to_owned(),
            ));
        }
        let recomputed = arkret_canonical::canonical_json_bytes(&request)?;
        if recomputed != canonical_request {
            return Err(Error::Protocol(
                "persisted bootstrap cancel request is not byte-exact canonical JSON".to_owned(),
            ));
        }
        Ok(Self {
            request,
            canonical_request,
        })
    }

    pub fn request(&self) -> &CancelDeviceBootstrapRequestBody {
        &self.request
    }

    pub fn canonical_request(&self) -> &[u8] {
        &self.canonical_request
    }
}

impl PartialEq for PreparedDeviceBootstrapCancel {
    fn eq(&self, other: &Self) -> bool {
        self.canonical_request == other.canonical_request
    }
}

impl Eq for PreparedDeviceBootstrapCancel {}

pub trait DeviceBootstrapCancelTransport {
    fn cancel_device_bootstrap<'a>(
        &'a self,
        canonical_request: &'a [u8],
    ) -> BoxSessionFuture<'a, CancelDeviceBootstrapOutcome>;
}

impl DeviceBootstrapCancelTransport for arkret_http_client::Client {
    fn cancel_device_bootstrap<'a>(
        &'a self,
        canonical_request: &'a [u8],
    ) -> BoxSessionFuture<'a, CancelDeviceBootstrapOutcome> {
        Box::pin(async move {
            self.post_canonical_bytes_with_options(
                CANCEL_DEVICE_BOOTSTRAP_PATH,
                canonical_request,
                &arkret_http_client::ClientRequestOptions::new(),
            )
            .await
            .map_err(Into::into)
        })
    }
}

pub async fn send_prepared_device_bootstrap_cancel<T>(
    transport: &T,
    prepared: &PreparedDeviceBootstrapCancel,
) -> Result<CancelDeviceBootstrapOutcome>
where
    T: DeviceBootstrapCancelTransport,
{
    let outcome = transport
        .cancel_device_bootstrap(prepared.canonical_request())
        .await?;
    outcome
        .validate_against(prepared.request())
        .map_err(|error| Error::Protocol(error.to_string()))?;
    Ok(outcome)
}

#[cfg(test)]
mod tests {
    use std::sync::Mutex;

    use super::*;

    fn hash(byte: char) -> Hash {
        Hash::new(format!("sha256:{}", byte.to_string().repeat(64))).unwrap()
    }

    fn prepared() -> PreparedDeviceBootstrapCancel {
        PreparedDeviceBootstrapCancel::prepare(
            ProtocolOpaqueId::new("bootstrap-transaction-fixture").unwrap(),
            hash('a'),
            IdempotencyKey::new("bootstrap-cancel-fixture").unwrap(),
        )
        .unwrap()
    }

    #[test]
    fn restore_keeps_the_first_canonical_request_bytes() {
        let first = prepared();
        let restored =
            PreparedDeviceBootstrapCancel::restore(first.canonical_request().to_vec()).unwrap();
        assert_eq!(restored, first);

        let mut noncanonical = first.canonical_request().to_vec();
        noncanonical.insert(1, b' ');
        assert!(PreparedDeviceBootstrapCancel::restore(noncanonical).is_err());
    }

    #[derive(Default)]
    struct RecordingTransport {
        requests: Mutex<Vec<Vec<u8>>>,
    }

    impl DeviceBootstrapCancelTransport for RecordingTransport {
        fn cancel_device_bootstrap<'a>(
            &'a self,
            canonical_request: &'a [u8],
        ) -> BoxSessionFuture<'a, CancelDeviceBootstrapOutcome> {
            self.requests
                .lock()
                .unwrap()
                .push(canonical_request.to_vec());
            let request: CancelDeviceBootstrapRequestBody =
                arkret_canonical::from_canonical_json_slice(canonical_request).unwrap();
            Box::pin(async move {
                let placeholder = hash('0');
                let mut outcome = CancelDeviceBootstrapOutcome::Cancelled {
                    transaction_id: request.transaction_id,
                    outcome_digest: placeholder,
                };
                let digest = outcome.recompute_outcome_digest().unwrap();
                let CancelDeviceBootstrapOutcome::Cancelled { outcome_digest, .. } = &mut outcome
                else {
                    unreachable!()
                };
                *outcome_digest = digest;
                Ok(outcome)
            })
        }
    }

    #[tokio::test]
    async fn retries_send_the_same_body_and_validate_the_terminal_outcome() {
        let prepared = prepared();
        let transport = RecordingTransport::default();
        let first = send_prepared_device_bootstrap_cancel(&transport, &prepared)
            .await
            .unwrap();
        let replay = send_prepared_device_bootstrap_cancel(&transport, &prepared)
            .await
            .unwrap();
        assert_eq!(
            arkret_canonical::canonical_json_bytes(&first).unwrap(),
            arkret_canonical::canonical_json_bytes(&replay).unwrap()
        );
        assert_eq!(
            transport.requests.lock().unwrap().as_slice(),
            &[
                prepared.canonical_request().to_vec(),
                prepared.canonical_request().to_vec()
            ]
        );
    }
}
